const lessons=[{"sentences":[{"speaker":"A","text":"Hello Mark because you arrived early I want to ask if we can swap our shifts today.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.340041666666667},{"speaker":"B","text":"Hi Sarah I might be able to help although I need to know what time your shift starts.","position":2,"audioStartSeconds":5.540041666666666,"audioEndSeconds":10.313083333333333},{"speaker":"A","text":"My original slot begins at two o'clock when the main registration desk gets very busy.","position":3,"audioStartSeconds":10.513083333333332,"audioEndSeconds":16.287041666666667},{"speaker":"B","text":"That is a difficult hour because I planned to attend an important volunteer meeting then.","position":4,"audioStartSeconds":16.487041666666666,"audioEndSeconds":21.655333333333335},{"speaker":"A","text":"The meeting finishes by three so you could easily take over the desk after that.","position":5,"audioStartSeconds":21.855333333333334,"audioEndSeconds":26.919791666666665},{"speaker":"B","text":"If I do that who will watch the entrance doors while you take your break.","position":6,"audioStartSeconds":27.119791666666668,"audioEndSeconds":31.411041666666666},{"speaker":"A","text":"David agreed to cover the entrance until three o'clock if someone helps him with setup.","position":7,"audioStartSeconds":31.611041666666665,"audioEndSeconds":36.76566666666667},{"speaker":"B","text":"I can help David with the morning setup before my meeting starts if you want.","position":8,"audioStartSeconds":36.965666666666664,"audioEndSeconds":41.69504166666667},{"speaker":"A","text":"That solves our problem perfectly because everything will remain fully covered all afternoon.","position":9,"audioStartSeconds":41.895041666666664,"audioEndSeconds":47.539375},{"speaker":"B","text":"Should we inform the supervisor about this temporary change before we start.","position":10,"audioStartSeconds":47.739375,"audioEndSeconds":52.66204166666667},{"speaker":"A","text":"Yes we should send her a quick message so she knows who is working where.","position":11,"audioStartSeconds":52.86204166666667,"audioEndSeconds":57.359458333333336},{"speaker":"B","text":"I will write the email right now while you check the registration materials.","position":12,"audioStartSeconds":57.55945833333333,"audioEndSeconds":62.237291666666664},{"speaker":"A","text":"Thank you so much for being so flexible with your busy schedule today.","position":13,"audioStartSeconds":62.43729166666667,"audioEndSeconds":66.93770833333333},{"speaker":"B","text":"You are welcome because working together makes these big community events much easier.","position":14,"audioStartSeconds":67.13770833333334,"audioEndSeconds":72.52445833333333}],"questions":[{"prompt":"Why does Sarah approach Mark at the beginning of the conversation?","options":["To ask him to swap their volunteer shifts.","To invite him to an important afternoon meeting.","To complain about the busy registration desk."],"answer":"A","evidenceSentence":1,"evidence":"ask if we can swap our shifts today","explanation":"Sarah đến gặp Mark để hỏi xem họ có thể đổi ca trực cho nhau hay không."},{"prompt":"What initial problem does Mark mention regarding Sarah's original time slot?","options":["He will be eating lunch at that time.","He has an important volunteer meeting then.","He finishes his work much earlier in the day."],"answer":"B","evidenceSentence":4,"evidence":"planned to attend an important volunteer meeting then","explanation":"Mark giải thích rằng anh ấy có một cuộc họp tình nguyện quan trọng vào thời gian đó."},{"prompt":"When does Mark's scheduled meeting finish?","options":["At two o'clock.","At three o'clock.","At four o'clock."],"answer":"B","evidenceSentence":5,"evidence":"The meeting finishes by three","explanation":"Cuộc họp của Mark kết thúc vào lúc ba giờ."},{"prompt":"What task does Mark offer to help David with?","options":["The registration desk setup.","The morning setup.","The entrance door monitoring."],"answer":"B","evidenceSentence":8,"evidence":"help David with the morning setup","explanation":"Mark đề nghị giúp David chuẩn bị vào buổi sáng trước cuộc họp."},{"prompt":"What do they decide to do before starting their new duties?","options":["Send a message to the supervisor.","Take a long break together.","Print more registration materials."],"answer":"A","evidenceSentence":11,"evidence":"send her a quick message","explanation":"Họ quyết định gửi tin nhắn nhanh cho người giám sát về sự thay đổi này."},{"prompt":"What will Mark do immediately after the conversation?","options":["Check the registration materials.","Write an email to the supervisor.","Go straight to the entrance doors."],"answer":"B","evidenceSentence":12,"evidence":"I will write the email right now","explanation":"Mark nói anh ấy sẽ viết email ngay bây giờ trong khi Sarah kiểm tra tài liệu đăng ký."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
